import { useEffect } from 'react'

export default function MarqueeStats() {
	useEffect(() => {
		const section = document.querySelector('.marquee-stats-block')
		if (!section) return

		const cardContainers = section.querySelectorAll('.framer-11aqw1k')
		if (!cardContainers.length) return

		const configs = [
			{ target: 1000, suffix: '+', useComma: true },
			{ target: 90, suffix: '%+', useComma: false },
			{ target: 50, suffix: '+', useComma: false },
		]

		let animated = false

		const animateCounters = () => {
			if (animated) return
			animated = true

			cardContainers.forEach((container) => {
				const valueParagraphs = container.querySelectorAll('.framer-1cjyfz3 p')
				valueParagraphs.forEach((p, idx) => {
					const config = configs[idx % configs.length]
					const duration = 1600
					const startTime = performance.now()

					const updateCount = (currentTime) => {
						const elapsed = currentTime - startTime
						const progress = Math.min(1, elapsed / duration)
						// easeOutExpo
						const ease = progress === 1 ? 1 : 1 - 2 ** (-10 * progress)
						const currentVal = Math.round(ease * config.target)

						const formatted = config.useComma
							? currentVal.toLocaleString('en-US') + config.suffix
							: currentVal + config.suffix

						p.textContent = formatted

						if (progress < 1) {
							requestAnimationFrame(updateCount)
						} else {
							// Settle spring pop: 1 -> 1.08 -> 1
							p.style.display = 'inline-block'
							p.style.transition = 'transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)'
							p.style.transform = 'scale(1.08)'
							setTimeout(() => {
								p.style.transform = 'scale(1)'
							}, 300)
						}
					}

					requestAnimationFrame(updateCount)
				})
			})
		}

		const observer = new IntersectionObserver(
			(entries) => {
				entries.forEach((entry) => {
					if (entry.isIntersecting) {
						animateCounters()
						observer.disconnect()
					}
				})
			},
			{ threshold: 0.25 },
		)

		cardContainers.forEach((el) => observer.observe(el))

		return () => observer.disconnect()
	}, [])

	return (
		<div
			className="marquee-stats-block"
			style={{ display: 'contents' }}
			dangerouslySetInnerHTML={{ __html: content }}
		/>
	)
}
